        beta.hat[i] <- lm.cov(mcov, y, c(x, pa1))
        if (verbose)
          cat("Fit - y:", y, "x:", c(x, pa1), "|b.hat=",
              beta.hat[i], "\n")
      }
    }
  }
  unname(beta.hat)
}


