if IF_GP
    Thresh = 1E-4;
    [eig_Ky, eiy] = eigdec((Kyy+Kyy')/2, min(400, floor(T/4))); % /2
    covfunc = {'covSum', {'covSEard','covNoise'}};
    %     covfunc = {'covSum', {'covMatern3ard','covNoise'}};

    logtheta0 = [log(width)*ones(d,1);  log(Wt); 0; log(sqrt(0.1))];
    fprintf('Optimization hyperparameters in GP regression:\n');

    IIy = find(eig_Ky > max(eig_Ky) * Thresh); eig_Ky = eig_Ky(IIy); eiy = eiy(:,IIy);
    [logtheta_y, fvals_y, iter_y] = minimize(logtheta0, 'gpr_multi', -350, covfunc, [X c_indx], 2*sqrt(T) *eiy * diag(sqrt(eig_Ky))/sqrt(eig_Ky(1)));
    exp(logtheta_y),

    covfunc_z = {'covSEard'};
    Kxt = feval(covfunc_z{:}, logtheta_y, [X c_indx]);

    % Note: in the conditional case, no need to do centering, as the regression
    % will automatically enforce that.

    % Kernel matrices of the errors
    invK = pdinv(Kxt + exp(2*logtheta_y(end))*eye(T));

%         Kxx = kernel(X, X, [1/exp(2*logtheta_y(1)),1]);
%         Ktt = kernel((1:T)', (1:T)', [1/exp(2*logtheta_y(d+1)),1]);
    Kxx = feval(covfunc_z{:}, logtheta_y([1:d,d+2]), X);
    Ktt = feval(covfunc_z{:}, logtheta_y([d+1,d+2]), c_indx);
else
    Kxx = kernel(X, X, [theta,1]);
    Kyy = kernel(Y, Y, [theta,1]);
    Ktt = kernel(c_indx, c_indx, [1/Wt^2,1]);
    invK = pdinv( Kxx.* Ktt +  lambda * eye(T));
end
Kxx3 = Kxx^3; %^3

prod_invK =  invK * Kyy * invK;
% now finding Ml

Ml = 1/T^2 * Ktt*( Kxx3 .* prod_invK) * Ktt;

% Len = floor(T/50);
% for c = 1:50
%     cc = Len*(c-1)+1;
%     for c1 = c:50
%         fprintf('.');
%         cc1 = Len*(c1-1)+1;
%         % Ml(c,c1) = trace(diag(Ktt(:,cc)) *  Kxx3 * diag(Ktt(:,cc1)) * prod_invK);
%         Ml(c,c1) = trace( ((Ktt(:,cc) * Ktt(:,cc1)' ) .* Kxx3) * prod_invK );
%         if c1>c
%             Ml(c1,c) = Ml(c,c1);
%         end
%     end
% end
% Ml = 1/T^2 * Ml;

% the square distance
D = diag(diag(Ml)) * ones(size(Ml)) + ones(size(Ml)) * diag(diag(Ml)) - 2*Ml;

% Gaussian kernel
sigma2_square = median( D(find(tril(ones(size(D)),-1))) );
Mg = exp(-D/sigma2_square/2);


[Yg, eigVectorg, eigValueg]=kPCA_kernel_orig(Mg,3);
[Yl, eigVectorl, eigValuel]=kPCA_kernel_orig(Ml,3);
% figure, plot(Yg(:,1),'b'); hold on; plot(Yg(:,2),'k--'); title('VIsualization of change in PA^i \rightarrow V^i (with Gaussian kernel)')
% legend(['First component of \lambda_i (eigenvalue: ' num2str(eigValueg(1)) ')'],['Second component of \lambda_i (eigenvalue: ' num2str(eigValueg(2)) ')']);

% figure, plot(Yl(:,1),'b'); hold on; plot(Yl(:,2),'k--'); title('VIsualization of change in PA^i \rightarrow V^i (with linear kernel)')
% legend(['First component of \lambda_i (eigenvalue: ' num2str(eigValuel(1)) ')'],['Second component of \lambda_i (eigenvalue: ' num2str(eigValuel(2)) ')']);

info.rho       = NaN;
info.iters     = NaN;
info.acrelerr  = NaN;
info.acminlags = NaN;
info.aclags    = NaN;

G = [];

% construct VAR coefficients for 1-lag problem

A1 = [reshape(A,n,p*n); eye(pn1) zeros(pn1,n)];

% calculate spectral radius

info.rho = max(abs(eig(A1)));

if info.rho >= 1
    info.error = 1;
    info.errmsg = 'unstable VAR (unit root)';
    return
end

% construct residual covariances for 1-lag problem

if ~isposdef(SIG);
    info.error = 2;
    info.errmsg = 'residuals covariance matrix not positive-definite';
    return;
end

SIG1 = [SIG zeros(n,pn1); zeros(pn1,n) zeros(pn1)];

% solve the Lyapunov equation for the 1-lag covariance matrix

try
    if aitr
        [G1,info.iters] = dlyap_aitr(A1,SIG1,maxiters,maxrelerr); % experimental: fast, but needs more testing
    else
%       G1 = dlyap(A1,SIG1);           % dlyap seems to work better here without balancing, which seems to break positive-definitiveness
        G1 = lyapslv('D',A1,[],-SIG1); % sometimes. However lyapslv is not an official interface, so this could conceivably break in future.
    end
catch except
    info.error = 3;
    info.errmsg = ['Lyapunov equation solver failed: ' except.message];
    return
end

info.acrelerr = norm(A1*G1*A1'-G1+SIG1)/norm(SIG1); % this should be small (see below)

maxacrelerr = 1e-8; % probably shouldn't be hard-coded :-/
if info.acrelerr > maxacrelerr
    info.warnings = info.warnings+1;
    info.warnmsg{info.warnings} = sprintf('large relative error = %g (tolerance = %g)',info.acrelerr,maxacrelerr);
end

% estimate number of autocov lags

info.acminlags = ceil(log(acdectol)/log(info.rho)); % minimum lags to achieve specified tolerance

if     acmaxlags < 0  % use exactly -acmaxlags lags (not encouraged, hence undocumented!)
    info.aclags = -acmaxlags;
elseif acmaxlags > 0  % use at most acmaxlags lags
    info.aclags = min(info.acminlags,acmaxlags);
else                  % acmaxlags == 0 - use minimum acceptable lags (recommended)
    info.aclags = info.acminlags;
end

if info.aclags < info.acminlags
    info.warnings = info.warnings+1;
    info.warnmsg{info.warnings} = sprintf('too few autocovariance lags = %d (minimum = %d)',info.aclags,info.acminlags);
end

if ~isposdef(G1);
    info.error = 4;
    info.errmsg = '1-lag covariance matrix not positive-definite';
    return
end

q = info.aclags;
q1 = q+1;

