\item{dscale}{the fraction of the standard deviation of the outcome variable for the control group used as the alternative hypothesis for asymptotic power calculation. Default is 0.5.}

\item{ci}{calculates a confidence interval for the treatment effect. The first element specifies alpha (typically 0.05 or 0.01); remaining elements specify a treatment-effect grid. TSLS uses normal intervals. Polynomial sharp-design mean contrasts use normal intervals unless a grid is supplied. Other cases invert tests over a grid; polynomial fuzzy Anderson-Rubin requires an explicit grid. At \code{p = 0}, test inversion uses \code{rdsensitivity}. Use a sufficiently wide grid to avoid truncating the confidence set.}

\item{interfci}{the level for Rosenbaum's confidence interval under arbitrary interference between units.}

\item{bernoulli}{the probabilities of treatment for each unit when assignment mechanism is a Bernoulli trial. This option should be specified as a vector of length equal to the length of the outcome and running variables.}

\item{reps}{the number of replications (default is 1000).}

\item{seed}{the seed to be used for the randomization test.}

\item{covariates}{the covariates used by \code{rdwinselect} to choose the window when \code{wl} and \code{wr} are not specified. This should be a matrix of size n x k where n is the total sample size and k is the number of covariates.}

\item{obsmin}{the minimum number of observations above and below the cutoff in the smallest window used by the companion command \code{rdwinselect}. Default is 10.}

\item{wmin}{the smallest window to be used (if \code{obsmin} is not specified) by the companion command \code{rdwinselect}. Specifying both \code{wmin} and \code{obsmin} returns an error.}

\item{wobs}{the number of observations to be added on each side of the cutoff at each step.}

\item{wstep}{the increment in window length (if \code{obsstep} is not specified) by the companion command \code{rdwinselect}. Specifying both \code{obsstep} and \code{wstep} returns an error.}

\item{wasymmetric}{allows for asymmetric windows around the cutoff when \code{wobs} is specified.}

\item{wmasspoints}{specifies that the running variable is discrete and each masspoint should be used as a window.}

\item{nwindows}{the number of windows to be used by the companion command \code{rdwinselect}. Default is 10.}

\item{dropmissing}{drop rows with missing values in covariates when calculating windows.}

\item{rdwstat}{the statistic to be used by the companion command \code{rdwinselect} (see the corresponding help file for options). Default option is \code{diffmeans}.}

\item{approx}{forces the companion command \code{rdwinselect} to conduct the covariate balance tests using a large-sample approximation instead of finite-sample exact randomization inference methods.}

\item{rdwreps}{the number of replications to be used by the companion command \code{rdwinselect}. Default is 1000.}

\item{level}{the minimum accepted value of the p-value from the covariate balance tests to be used by the companion command \code{rdwinselect}. Default is .15.}

\item{plot}{draws a scatter plot of the minimum p-value from the covariate balance test against window length implemented by the companion command \code{rdwinselect}.}

\item{firststage}{reports the results from the first step when using tsls.}

\item{obsstep}{the minimum number of observations to be added on each side of the cutoff for the sequence of fixed-increment nested windows. Default is 2. This option is deprecated and only included for backward compatibility.}

\item{vce}{heteroskedasticity-consistent variance estimator for \code{p > 0}: \code{HC1}, \code{HC2}, or \code{HC3} (default). Ignored when \code{p = 0}.}

\value{
A list containing:
\item{sumstats}{matrix of full-sample and window-specific summary statistics.}
\item{obs.stat}{observed statistic or statistics.}
\item{p.value}{randomization p-value or p-values; \code{NA} when \code{p > 0}.}
\item{asy.pvalue}{asymptotic p-value or p-values.}
\item{window}{chosen window endpoints.}
\item{ci}{confidence interval; included only when \code{ci} is specified.}
\item{interf.ci}{confidence interval under interference; included only when
\code{interfci} is specified.}

\item{p.requested, p}{requested and effective polynomial degrees.}
\item{vce}{HC variance estimator; \code{NA} when \code{p = 0}.}
\item{inference}{inference method used.}
\item{se}{standard error; included when the effective \code{p > 0}.}
}
\description{
\code{rdrandinf} implements randomization inference and related methods for RD designs,
using observations in a specified or data-driven selected window around the cutoff where
local randomization is assumed to hold.
}
\details{
With \code{p > 0}, mean contrasts, fuzzy Anderson-Rubin tests, and fuzzy TSLS/Wald
use large-sample normal inference from the full polynomial regression, with
HC3 standard errors by default; no randomization p-value is computed.
HC3 does not guarantee finite-sample size control; TSLS/Wald also requires a sufficiently strong first stage.
TSLS uses structural residuals and leverage from projected second-stage regressors.
Fuzzy Anderson-Rubin confidence sets require an explicit treatment-effect grid in ci.
For ksmirnov, ranksum, all, or interfci, a positive p is replaced by \code{p = 0}
and a warning is issued at the end. With \code{p = 0}, existing inference methods
and variance defaults are retained; TSLS tests honor \code{nulltau} and the requested CI level.

\item{wlist_right}{right endpoints of the candidate windows.}
\item{results}{matrix containing the minimum covariate-balance p-value,
selected covariate index, binomial-test p-value, sample sizes below and
above the cutoff, and window endpoints for each candidate window.}
\item{summary}{matrix of sample-size summaries by side of the cutoff.}

\item{p.requested, p}{requested and effective polynomial degrees.}
\item{vce}{HC variance estimator; \code{NA} when \code{p = 0}.}
\item{inference}{inference method used.}
}
\description{
\code{rdwinselect} implements a window-selection procedure based on balance
 tests for RD designs under local randomization. Specifically, it constructs a
 sequence of nested windows around the RD cutoff and reports binomial tests for
 the running variable and covariate balance tests for the covariates (if
 specified). The recommended window is the largest window around the cutoff
 such that the minimum p-value from the balance tests is larger than a
 prespecified level for all nested (smaller) windows. By default, the p-values
 are calculated using randomization inference methods.
}
\details{
With \code{p > 0}, mean balance tests use large-sample normal inference from the full
polynomial regression, with HC3 standard errors by default, regardless of approx.
For ksmirnov, ranksum, or hotelling, a positive p is replaced by \code{p = 0}
and a warning is issued at the end. Inference with \code{p = 0} is unchanged.

\arguments{
\item{Y}{a vector containing the values of the outcome variable.}

\item{R}{a vector containing the values of the running variable.}

\item{cutoff}{the RD cutoff (default is 0).}

\item{wl}{the left limit of the window. The default takes the minimum of the running variable.}

\item{wr}{the right limit of the window. The default takes the maximum of the running variable.}

\item{statistic}{the randomization test statistic to be used. Allowed options are \code{diffmeans} (difference in means statistic), \code{ksmirnov} (Kolmogorov-Smirnov statistic), \code{ranksum} (Wilcoxon-Mann-Whitney standardized statistic), and \code{all}. Default option is \code{diffmeans}. The statistic \code{ttest} is equivalent to \code{diffmeans} and included for backward compatibility.}

\item{p}{the order of the polynomial for the outcome adjustment model (default is 0).}

\item{evall}{the point to the left of the cutoff at which the adjusted outcome is evaluated. Default is the cutoff value.}

\item{evalr}{the point to the right of the cutoff at which the adjusted outcome is evaluated. Default is the cutoff value.}

\item{kernel}{specifies the type of kernel to use as a weighting scheme. Allowed kernel types are \code{uniform} (uniform kernel), \code{triangular} (triangular kernel), and \code{epan} (Epanechnikov kernel). Default is \code{uniform}.}

\item{fuzzy}{indicates that the RD design is fuzzy. \code{fuzzy} can be specified as a vector containing the values of the endogenous treatment variable, or as a list where the first element is the vector of endogenous treatment values and the second element is a string containing the statistic to be used. Allowed statistics are \code{ar} or \code{itt} (Anderson-Rubin/intention-to-treat statistic) and \code{tsls} (2SLS statistic). Default statistic is \code{ar}. The \code{tsls} statistic relies on a large-sample approximation.}

\item{nulltau}{the value of the treatment effect under the null hypothesis (default is 0).}

\item{d}{the effect size for asymptotic power calculation. Default is 0.5 times the standard deviation of the outcome variable for the control group.}

\item{dscale}{the fraction of the standard deviation of the outcome variable for the control group used as the alternative hypothesis for asymptotic power calculation. Default is 0.5.}

\item{ci}{calculates a confidence interval for the treatment effect. The first element specifies alpha (typically 0.05 or 0.01); remaining elements specify a treatment-effect grid. TSLS uses normal intervals. Polynomial sharp-design mean contrasts use normal intervals unless a grid is supplied. Other cases invert tests over a grid; polynomial fuzzy Anderson-Rubin requires an explicit grid. At \code{p = 0}, test inversion uses \code{rdsensitivity}. Use a sufficiently wide grid to avoid truncating the confidence set.}

\item{interfci}{the level for Rosenbaum's confidence interval under arbitrary interference between units.}

\item{bernoulli}{the probabilities of treatment for each unit when assignment mechanism is a Bernoulli trial. This option should be specified as a vector of length equal to the length of the outcome and running variables.}

\item{reps}{the number of replications (default is 1000).}

\item{seed}{the seed to be used for the randomization test.}

\item{covariates}{the covariates used by \code{rdwinselect} to choose the window when \code{wl} and \code{wr} are not specified. This should be a matrix of size n x k where n is the total sample size and k is the number of covariates.}

\item{obsmin}{the minimum number of observations above and below the cutoff in the smallest window used by the companion command \code{rdwinselect}. Default is 10.}

\item{wmin}{the smallest window to be used (if \code{obsmin} is not specified) by the companion command \code{rdwinselect}. Specifying both \code{wmin} and \code{obsmin} returns an error.}

\item{wobs}{the number of observations to be added on each side of the cutoff at each step.}

\item{wstep}{the increment in window length (if \code{obsstep} is not specified) by the companion command \code{rdwinselect}. Specifying both \code{obsstep} and \code{wstep} returns an error.}

\item{wasymmetric}{allows for asymmetric windows around the cutoff when \code{wobs} is specified.}

\item{wmasspoints}{specifies that the running variable is discrete and each masspoint should be used as a window.}

\item{nwindows}{the number of windows to be used by the companion command \code{rdwinselect}. Default is 10.}

\item{dropmissing}{drop rows with missing values in covariates when calculating windows.}

\item{rdwstat}{the statistic to be used by the companion command \code{rdwinselect} (see the corresponding help file for options). Default option is \code{diffmeans}.}

\item{approx}{forces the companion command \code{rdwinselect} to conduct the covariate balance tests using a large-sample approximation instead of finite-sample exact randomization inference methods.}

\item{rdwreps}{the number of replications to be used by the companion command \code{rdwinselect}. Default is 1000.}

\item{level}{the minimum accepted value of the p-value from the covariate balance tests to be used by the companion command \code{rdwinselect}. Default is .15.}

\item{plot}{draws a scatter plot of the minimum p-value from the covariate balance test against window length implemented by the companion command \code{rdwinselect}.}

\item{firststage}{reports the results from the first step when using tsls.}

\item{obsstep}{the minimum number of observations to be added on each side of the cutoff for the sequence of fixed-increment nested windows. Default is 2. This option is deprecated and only included for backward compatibility.}

\item{vce}{heteroskedasticity-consistent variance estimator for \code{p > 0}: \code{HC1}, \code{HC2}, or \code{HC3} (default). Ignored when \code{p = 0}.}

\value{
A list containing:
\item{sumstats}{matrix of full-sample and window-specific summary statistics.}
\item{obs.stat}{observed statistic or statistics.}
\item{p.value}{randomization p-value or p-values; \code{NA} when \code{p > 0}.}
\item{asy.pvalue}{asymptotic p-value or p-values.}
\item{window}{chosen window endpoints.}
\item{ci}{confidence interval; included only when \code{ci} is specified.}
\item{interf.ci}{confidence interval under interference; included only when
\code{interfci} is specified.}

\item{p.requested, p}{requested and effective polynomial degrees.}
\item{vce}{HC variance estimator; \code{NA} when \code{p = 0}.}
\item{inference}{inference method used.}
\item{se}{standard error; included when the effective \code{p > 0}.}
}
